import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.CDU0sSpB.js";const h=JSON.parse('{"title":"Phase 2–6 capability status","description":"Implemented, verified, and deliberately open capabilities by phase, without treating a page as a closed loop.","frontmatter":{"title":"Phase 2–6 capability status","description":"Implemented, verified, and deliberately open capabilities by phase, without treating a page as a closed loop.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/capabilities.md","filePath":"en/delivery/capabilities.md","lastUpdated":null}'),s={name:"en/delivery/capabilities.md"};function n(i,e,d,c,l,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="phase-2–6-capability-status" tabindex="-1">Phase 2–6 capability status <a class="header-anchor" href="#phase-2–6-capability-status" aria-label="Permalink to &quot;Phase 2–6 capability status&quot;">​</a></h1><p class="lead">This page records only what the current code and real runs can prove. Status values are &quot;code loop implemented&quot;, &quot;partial&quot;, and &quot;not implemented&quot;; they are not interchangeable.</p><p>Baseline checked on 2026-11-07. <code>npm test</code> passes 40 files and 199 tests; <code>npm run typecheck</code>, <code>npm run build</code>, and <code>npm run docs:build</code> pass.</p><h2 id="agent-runtime-closure" tabindex="-1">Agent runtime closure <a class="header-anchor" href="#agent-runtime-closure" aria-label="Permalink to &quot;Agent runtime closure&quot;">​</a></h2><ul><li><strong>Implemented:</strong> <code>native</code> and <code>codex</code> executors are peers. Executor identity is written into runs and manifests. General tasks default to native; explicit coding/repository tasks use Codex. Failures never silently switch.</li><li><strong>Implemented:</strong> Four model protocols (OpenAI Chat, OpenAI Responses, Anthropic Messages, Gemini) normalized into streaming text and tool calls; providers are selectable or custom.</li><li><strong>Implemented:</strong> <code>@hearth/agent-runtime</code> is a single-agent tool loop with read, search, write, edit, patch, shell, fetch, ask-user, and finish tools; task-scoped read/write roots, network hosts, and tool allowlists.</li><li><strong>Implemented:</strong> Turn, tool-call, token, and duration budgets; checkpoints on every model turn and tool step; resume from waiting-for-input with the user&#39;s answer; retry missing artifacts with prior agent context, at most twice.</li><li><strong>Implemented:</strong> Tasks that need network access or engineering workspace permissions first produce a chat proposal; the task is created only after confirmation. General tasks dispatch directly.</li><li><strong>UI result:</strong> Task pages show executor, phase, tokens, duration, and result. Detail pages show the user-facing summary and declared artifacts first; intermediate JSON, command logs, and checkpoints are collapsed.</li></ul><p>This is a code-and-test closure, not proof of long-running acceptance in a real user environment.</p><h2 id="phase-2" tabindex="-1">Phase 2 <a class="header-anchor" href="#phase-2" aria-label="Permalink to &quot;Phase 2&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sub-stage</th><th>Status</th><th>Implemented</th><th>Deliberately open</th></tr></thead><tbody><tr><td>2.1 Read-only sources</td><td>Partial</td><td>Local files, knowledge bases, public web sources; domain allowlist; source status, read time, errors, incremental reads, dedupe, disconnect, reconnect, clear</td><td>Email and calendar show &quot;not configured&quot;; no credentials, reads, or permission verification</td></tr><tr><td>2.2 Documents, tables, and web material</td><td>Basic loop implemented</td><td>TXT, Markdown, CSV, JSON, HTML, PDF, DOCX, XLSX extraction; page, paragraph, worksheet, range, and gap records; web snapshots and source items</td><td>Complex layouts, scanned OCR, per-page citation targeting, and spreadsheet formula fidelity</td></tr><tr><td>2.3 Drafting, approval, and external writes</td><td>Partial</td><td>Editable, savable, discardable drafts; one-time, short-lived approval; approved effects write to the local outbox with receipts; reject/expiry updates draft state</td><td>Writes only local <code>.hearth/outbox</code> files; no mail server, calendar, or other external systems</td></tr><tr><td>2.4 Everyday content acceptance</td><td>Not done</td><td>Automated tests and isolated-instance coverage of sources, extraction, and outbox</td><td>No 10–15 real everyday tasks with time, accuracy, recovery, and user willingness records</td></tr></tbody></table><p>The local outbox is not a fake success: the UI states that it writes locally and does not send. It must not be called &quot;sent&quot; before a real mail account is connected.</p><h2 id="phase-3" tabindex="-1">Phase 3 <a class="header-anchor" href="#phase-3" aria-label="Permalink to &quot;Phase 3&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sub-stage</th><th>Status</th><th>Implemented</th><th>Deliberately open</th></tr></thead><tbody><tr><td>3.1 Connect and inspect a desktop device</td><td>Partial</td><td>Six-digit pairing, device token, pairing and capability approvals separated; observation, control, and UI automation authorized separately; app allowlist; online state and revocation</td><td>No tray or always-on &quot;under control&quot; indicator; Windows same-machine helper only</td></tr><tr><td>3.2 Observe and take over</td><td>Partial</td><td>Screenshot bound to the session; pause, resume, takeover, hand-back, terminate; takeover cancels pending input and advances the control epoch; user-idle check; frames expire after two minutes</td><td>Sensitive-area masking, long recording, and full desktop snapshots</td></tr><tr><td>3.3 Tiered desktop actions</td><td>Partial</td><td>Target-app binding and pre-action focus check; clicks, short text, Enter/Tab/Escape/Ctrl+S; UIA invoke/setvalue allowlist; UWP host windows mapped through the UIA child process; command status and results; structured rejection</td><td>High-risk preview and confirmation, isolated desktop, snapshots, compensation, real UIA setvalue acceptance</td></tr><tr><td>3.4 Desktop acceptance</td><td>Not done</td><td>Isolated-port pairing, capability approval, observation, pause, resume, takeover, hand-back, and pro-mode expansion verified</td><td>No 5+ real desktop tasks with success rate, takeover count, and failure drills</td></tr></tbody></table><p>The Windows helper focuses the server-approved target app before observing or typing; it is not a background no-focus input channel. For UWP apps hosted by <code>ApplicationFrameHost</code>, it reads the UIA subtree and allows focus/observation only when a child process maps to the approved app, for example <code>CalculatorApp</code> to <code>calculator</code>. If the owner cannot be determined, it rejects instead of silently treating the host window as the target. A real UIA invoke was verified in Calculator: invoking &quot;2&quot; returned <code>InvokePattern</code> and changed the reading from <code>7</code> to <code>72</code>. The same chain completed &quot;observe → UIA action → automatic observe&quot; on an isolated paired device with command results and screenshots returned.</p><h2 id="phase-4" tabindex="-1">Phase 4 <a class="header-anchor" href="#phase-4" aria-label="Permalink to &quot;Phase 4&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sub-stage</th><th>Status</th><th>Implemented</th><th>Deliberately open</th></tr></thead><tbody><tr><td>4.1 Triggers and proactive suggestions</td><td>Code loop implemented</td><td>Six triggers: task enters a 24-hour due window, task fails or becomes recoverable, external result uncertain, approval waiting over two hours, new source item within 24 hours, queue backlog or long-running task; suggestions include source, why now, proposed action, impact, cost, risk, approval need, and priority; dedupe by event key with occurrence counts</td><td>Email and calendar triggers are disabled placeholders; proactive mode never executes high-risk actions directly</td></tr><tr><td>4.2 Proactive inbox</td><td>Code loop implemented</td><td>Priority inbox; accept, ignore, snooze, convert to task; accept and convert are separate; accept only records a decision, convert only creates a queued task without approving or replaying effects; ignored events are not rephrased and repushed</td><td>No multi-device or mobile inbox; no notification channel distribution, only the local web inbox</td></tr><tr><td>4.3 Mobile view, approval, takeover</td><td>Not implemented</td><td>None</td><td>No mobile PWA, pairing, push, mobile approval, or remote takeover; the only entry is the same-machine web control plane</td></tr><tr><td>4.4 Attention budget and acceptance</td><td>Partial</td><td>Daily cap 0–50, quiet hours, cooldown, aggregation window, temporary pause and resume; budget snapshot shows used/limit, quiet/paused state, and next allowed time; last seven days record delivered, accepted, ignored, converted, and completed; the &quot;needs you&quot; page collects pending approvals</td><td>No 5–10 real proactive tasks proving at most one interruption per task; no push delivery stats or long-term user-feel record</td></tr></tbody></table><p>The key boundary in phase four is &quot;a suggestion is not an execution&quot;. <code>accept</code> only changes suggestion state; only <code>convert</code> creates a new queued task, which then follows the normal executor, approval, and effect-ledger rules. A high-risk action does not bypass approval because it came from a proactive suggestion.</p><h2 id="phase-5" tabindex="-1">Phase 5 <a class="header-anchor" href="#phase-5" aria-label="Permalink to &quot;Phase 5&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sub-stage</th><th>Status</th><th>Implemented</th><th>Deliberately open</th></tr></thead><tbody><tr><td>5.1 Visible memory</td><td>Code loop implemented</td><td>Memory enters as a candidate and participates in recall only after confirmation; records type, subject key, scope, tags, source, confidence, sensitivity, validity, and version; recall scores task relevance and records reason and usage audit; injected context carries <code>trusted=&quot;false&quot;</code> and a &quot;cannot expand authority&quot; boundary; recall item and character budgets</td><td>Auto-capture is off by default and only captures &quot;experience&quot; from terminal tasks; no automatic user-fact extraction from email, web, or arbitrary documents</td></tr><tr><td>5.2 Correct, forget, export</td><td>Code loop implemented</td><td>Correction creates a new version and keeps history; same-subject conflicts are not silently overwritten and require left/right/merge; forgetting tombstones the current record and redacts historical versions, related events, and recall-audit matches; export omits forgotten bodies; sensitive memory is not recalled by default and <code>secret</code> memory is never recalled</td><td>Cross-device forgetting relies only on sync filtering and local copy boundaries; no remote erasure of previously exported files</td></tr><tr><td>5.3 Summarize and evaluate reusable methods</td><td>Code loop implemented</td><td>Candidate generated from terminal task traces; permissions are the intersection of source task capabilities and cannot expand; baseline/trial records success, duration, tokens, and approvals; evaluation distinguishes improved, flat, regressed, and insufficient; only candidates with improvement evidence and trial samples can be promoted; reject and rollback keep reasons and audit</td><td>&quot;Trial&quot; only reads existing terminal traces and does not re-execute a task, so it is not a live shadow executor; no long-term production comparison</td></tr><tr><td>5.4 Memory and evolution acceptance</td><td>Not done</td><td>API, service, and page-loop tests cover create, confirm, recall, correct, conflict, forget, export, trial, promote, and rollback</td><td>No real-user wrong-memory drill, wrong-method drill, before/after success/time/cost comparison, or full propose–evaluate–trial–adopt–rollback production acceptance</td></tr></tbody></table><p>The shared boundary is &quot;candidate first, confirmation second; evidence first, promotion second&quot;. Candidate methods never go live automatically, and memory content cannot act as an instruction that expands tools, network, or approval authority.</p><h2 id="phase-6" tabindex="-1">Phase 6 <a class="header-anchor" href="#phase-6" aria-label="Permalink to &quot;Phase 6&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sub-stage</th><th>Status</th><th>Implemented</th><th>Deliberately open</th></tr></thead><tbody><tr><td>6.1 Multi-device sync and switching</td><td>Partial</td><td>Each instance has an <code>instanceId</code>; peer token shown once, with hash and encrypted copy stored server-side; incremental pull by event sequence with dedupe; imported events rebuild projections; newer local task/memory/method state is not silently overwritten; conflicts keep both sides and require local/remote choice; sync UI shows peers, cursors, errors, and conflicts</td><td>Only filtered event projections sync; approvals, sources, outbox, devices, desktop, security, sync events, and sensitive/secret memory are not copied; artifact bodies, workspaces, and absolute paths are not synced; no real two-device switch or offline recovery acceptance</td></tr><tr><td>6.2 Device revocation and safe migration</td><td>Partial</td><td>Task leases carry TTL, owner, and epoch; expired leases can be taken over by another instance with an epoch advance; old-owner commits and results are rejected; device capabilities can be revoked, tokens rotated, devices re-paired; sync peers can rotate or revoke; global kill switch blocks approvals and scheduler restart with an audit record; security page shows state and audit</td><td>No dedicated cross-device artifact/workspace migration; no real lost-device drill proving a revoked device cannot approve, take over, or read; clearing the global stop does not auto-restart the executor</td></tr><tr><td>6.3 Backup, restore, and upgrade</td><td>Partial</td><td><code>*.hearth-backup</code> archive; scrypt (N=32768, r=8, p=1), AES-256-GCM, passphrase at least 12 characters; archive contains SQLite snapshot, required settings/audit/event metadata, and encrypted local <code>master.key</code>; restore writes temporary SQLite, checks <code>user_version</code>, schema, and <code>integrity_check</code>, rebuilds projections, copies in a transaction, rolls back on failure; preserves current <code>instanceId</code>, <code>createdAt</code>, and global stop state; clears old leases, pairings, and desktop session temporaries; old <code>/api/backup</code> returns <code>410</code></td><td>Excludes artifact bodies, task workspaces, source bodies, outbox attachments, screenshots/desktop temporaries, and external service data, so it is not a complete portable backup; no app version upgrade pipeline or failed-upgrade rollback; incompatible schema is rejected but has no real cross-version fixture drill</td></tr><tr><td>6.4 Long-running operation and v1.0 acceptance</td><td>Partial</td><td>Health snapshot includes uptime, memory, disk, schema, task counts, scheduler, approvals, kill switch, and last maintenance; maintenance clears expired approvals, recovers interrupted tasks, deletes expired leases/desktop commands/screenshots/pairings/temporaries without deleting tasks, memory, or artifacts; automatic maintenance every six hours after startup plus manual trigger; failure records failure and marks health degraded; diagnostics export includes health, maintenance, counts, and event types without paths, keys, or environment secrets; operations page shows health, maintenance, and backup boundaries</td><td>No multi-week continuous run, resource-drift data, real v1.0 install/upgrade/migration/exit acceptance, or full task-type regression matrix</td></tr></tbody></table><p>The phase-six backup boundary must stay visible: a recoverable database is not a portable artifact archive. After restore, tasks may reappear while artifact bodies, workspaces, or external attachments still need separate backup and verification.</p><h2 id="current-ui-boundary" tabindex="-1">Current UI boundary <a class="header-anchor" href="#current-ui-boundary" aria-label="Permalink to &quot;Current UI boundary&quot;">​</a></h2><p>The chat-first primary navigation currently exposes only <strong>Chat, Tasks, Devices, and Settings</strong>. Memory, methods, proactive inbox, sync, security, and operations already have server APIs, projections, and page components, but are not all wired back into the primary navigation. Read &quot;the capability exists&quot; in this page as one of:</p><ul><li><strong>Directly usable in the UI:</strong> chat, tasks, task detail, devices, settings.</li><li><strong>API and page components exist:</strong> memory, methods, proactive inbox, sync, security, operations, outbox, sources.</li><li><strong>Not implemented:</strong> mobile PWA, push, remote takeover, real email/calendar accounts.</li></ul><h2 id="borrowed-patterns-and-trade-offs" tabindex="-1">Borrowed patterns and trade-offs <a class="header-anchor" href="#borrowed-patterns-and-trade-offs" aria-label="Permalink to &quot;Borrowed patterns and trade-offs&quot;">​</a></h2><ul><li><strong>OpenClaw:</strong> pairing and capability approval are separate; commands are declared per device and authorized individually; an observation frame is the only basis for an action; takeover cancels pending input and advances the control epoch; unsupported actions are rejected. Hearth adopts these boundaries.</li><li><strong>Hermes:</strong> explicit capability lists, pre-action target verification, and session isolation. Hearth adopts app allowlists, target verification, and control epochs; it does not use background no-focus input because the current Windows layer cannot reliably prove focus stays in the approved window.</li><li><strong>OpenClaw proactive service:</strong> suggestions and execution are separate, and suggested actions return to the normal approval chain. Hearth adopts this and does not make proactive suggestions an auto-executor.</li><li><strong>Hermes health checks:</strong> expose drivers, permissions, runtime state, and last maintenance. Hearth adopts this with health snapshots, maintenance records, and redacted diagnostics.</li><li><strong>DeerFlow:</strong> task decomposition, method candidates, and evaluation layers are design references only. Hearth does not integrate DeerFlow or its multi-agent runtime.</li><li><strong>LoopX:</strong> only small-loop commits, state evidence, and acceptance boundaries are used as delivery method; LoopX is not a runtime dependency.</li></ul><h2 id="real-acceptance-still-missing" tabindex="-1">Real acceptance still missing <a class="header-anchor" href="#real-acceptance-still-missing" aria-label="Permalink to &quot;Real acceptance still missing&quot;">​</a></h2><ol><li>Read-only email and calendar accounts, real test accounts, and real send receipts.</li><li>10–15 everyday content tasks and at least 5 desktop tasks with complete acceptance records.</li><li>Sensitive-area masking, isolated desktop, snapshots, compensation, and high-risk actions.</li><li>Real UIA setvalue acceptance and failure drills for window loss, permission changes, and user takeover.</li><li>Phase-four mobile entry (PWA, pairing, push, remote approval, takeover) and 5–10 real proactive interruption tests.</li><li>Phase-five wrong-memory/wrong-method drills, full export verification, and before/after production comparison.</li><li>Phase-six real two-device sync, offline recovery, lost-device revocation, token rotation, backup restore, and migration verification.</li><li>Multi-week continuous operation, resource/state drift checks, upgrade rollback pipeline, and v1.0 acceptance.</li></ol><p>These gaps are deliberately left open; they are not replaced with simulated data or a UI that only looks complete.</p>',29)])])}const m=t(s,[["render",n]]);export{h as __pageData,m as default};
